  "milestones": [
    {
      "task": "find potted_fern",
      "milestone_id": "find_potted_fern",
      "description": "Uses position_near_with_facing because this is a find/locate/observe task. The player must navigate to the oak planks building and look at the potted fern placed at spawn-relative (7, 1, 7). max_distance=16 allows detection from within or near the building entrance, and facing_tolerance=60 ensures the player is actually looking toward the potted fern (not just passing by). This correctly models 'player can see the target object'.",
